function Calendar({
  mode = "single",
  selected,
  onSelect,
  month,
  defaultMonth,
  onMonthChange,
  min,
  max,
  disabled,
  className,
  size = "sm",
  today: todayProp,
  navigation = "both",
  header = "label",
  markedDays,
  markedLabel = "marked",
  disabledReason,
  reasonDefaultOpenDay,
  status = "ready",
  hoverDay,
}: CalendarProps) {
  const initialSelected: Date | undefined = mode === "range" ? (selected as DateRange | undefined)?.from : (selected as Date | undefined)
  const [uncontrolledMonth, setUncontrolledMonth] = React.useState<Date>(() => defaultMonth ?? initialSelected ?? new Date())
  const visibleMonth = month ?? uncontrolledMonth
  const [focusDay, setFocusDay] = React.useState<Date | null>(null)
  const focusPending = React.useRef(false)
  const gridRef = React.useRef<HTMLDivElement>(null)
  const headingId = React.useId()

  const [view, setView] = React.useState<"days" | "month" | "year">("days")
  const [periodPickerMonth, setPeriodPickerMonth] = React.useState<Date>(() => visibleMonth)
  const [previewDay, setPreviewDay] = React.useState<Date | null>(null)

  const days = React.useMemo(() => getMonthGrid(visibleMonth), [visibleMonth])
  const today = React.useMemo(() => startOfDay(todayProp ?? new Date()), [todayProp])
  const minDay = min ? startOfDay(min) : undefined
  const maxDay = max ? startOfDay(max) : undefined

  function outOfBounds(day: Date) {
    return (!!minDay && day < minDay) || (!!maxDay && day > maxDay)
  }

  function isDisabled(day: Date) {
    if (outOfBounds(day)) return true
    if (!disabled) return false
    return typeof disabled === "function" ? disabled(day) : disabled.some((d) => isSameDay(d, day))
  }

  function isMarked(day: Date) {
    if (!markedDays) return false
    return typeof markedDays === "function" ? markedDays(day) : markedDays.some((d) => isSameDay(d, day))
  }

  function clamp(day: Date) {
    if (minDay && day < minDay) return minDay
    if (maxDay && day > maxDay) return maxDay
    return day
  }

  const inVisibleMonth = (d?: Date) => !!d && d.getFullYear() === visibleMonth.getFullYear() && d.getMonth() === visibleMonth.getMonth()
  const inGrid = (d?: Date | null) => !!d && days.some((day) => isSameDay(day, d))

  const firstOfMonth = new Date(visibleMonth.getFullYear(), visibleMonth.getMonth(), 1)
  const activeDay: Date =
    (focusDay && inGrid(focusDay) ? focusDay : undefined) ??
    (inVisibleMonth(initialSelected) ? startOfDay(initialSelected!) : undefined) ??
    (inVisibleMonth(today) ? today : undefined) ??
    (inVisibleMonth(clamp(firstOfMonth)) ? clamp(firstOfMonth) : firstOfMonth)

  React.useEffect(() => {
    if (!focusPending.current) return
    const target = gridRef.current?.querySelector<HTMLElement>("[data-tab-stop]")
    if (target) {
      focusPending.current = false
      target.focus()
    }
  })

  function changeMonth(next: Date) {
    if (!month) setUncontrolledMonth(next)
    onMonthChange?.(next)
  }

  const prevMonthEnd = new Date(visibleMonth.getFullYear(), visibleMonth.getMonth(), 0)
  const nextMonthStart = new Date(visibleMonth.getFullYear(), visibleMonth.getMonth() + 1, 1)
  const prevBlocked = !!minDay && prevMonthEnd < minDay
  const nextBlocked = !!maxDay && nextMonthStart > maxDay

  function stepMonth(n: number) {
    changeMonth(new Date(visibleMonth.getFullYear(), visibleMonth.getMonth() + n, 1))
    setFocusDay(clamp(addMonthsClamped(activeDay, n)))
  }

  function handleDayClick(day: Date) {
    if (status !== "ready") return
    setFocusDay(day)
    if (isDisabled(day)) return
    setPreviewDay(null)
    if (mode === "range") {
      const range = (selected as DateRange | undefined) ?? {}
      const onRangeSelect = onSelect as CalendarRangeProps["onSelect"]
      if (!range.from || (range.from && range.to)) {
        onRangeSelect?.({ from: day, to: undefined })
      } else if (day < range.from) {
        onRangeSelect?.({ from: day, to: range.from })
      } else {
        onRangeSelect?.({ from: range.from, to: day })
      }
    } else {
      ;(onSelect as CalendarSingleProps["onSelect"])?.(day)
    }
  }

  function handleKeyDown(event: React.KeyboardEvent, day: Date) {
    let next: Date | undefined
    const weekday = (day.getDay() + 6) % 7
    switch (event.key) {
      case "ArrowLeft":
        next = addDays(day, -1)
        break
      case "ArrowRight":
        next = addDays(day, 1)
        break
      case "ArrowUp":
        next = addDays(day, -7)
        break
      case "ArrowDown":
        next = addDays(day, 7)
        break
      case "Home":
        next = addDays(day, -weekday)
        break
      case "End":
        next = addDays(day, 6 - weekday)
        break
      case "PageUp":
        next = addMonthsClamped(day, event.shiftKey ? -12 : -1)
        break
      case "PageDown":
        next = addMonthsClamped(day, event.shiftKey ? 12 : 1)
        break
      case "Enter":
      case " ":
        if (status !== "ready") return
        event.preventDefault()
        handleDayClick(day)
        return
      default:
        return
    }
    event.preventDefault()
    next = clamp(next)
    if (!inVisibleMonth(next)) changeMonth(new Date(next.getFullYear(), next.getMonth(), 1))
    focusPending.current = true
    setFocusDay(next)
  }

  function dayState(day: Date) {
    if (mode === "range") {
      const range = selected as DateRange | undefined
      const isStart = isSameDay(day, range?.from)
      const isEnd = isSameDay(day, range?.to)
      const inRange = !!range?.from && !!range?.to && day > range.from && day < range.to
      return { selected: isStart || isEnd, inRange, rangeStart: isStart, rangeEnd: isEnd }
    }
    return { selected: isSameDay(day, selected as Date | undefined), inRange: false, rangeStart: false, rangeEnd: false }
  }

  function daySelection(day: Date): CalendarDayProps["selection"] {
    if (mode !== "range") {
      return isSameDay(day, selected as Date | undefined) ? "single" : "none"
    }
    const range = selected as DateRange | undefined
    if (!range?.from) return "none"
    if (!range.to) {
      if (isSameDay(day, range.from)) return "single"
      const preview = hoverDay ?? previewDay
      if (preview && day > range.from && day < preview) return "preview"
      return "none"
    }
    if (isSameDay(day, range.from) && isSameDay(day, range.to)) return "single"
    if (isSameDay(day, range.from)) return "start"
    if (isSameDay(day, range.to)) return "end"
    if (day > range.from && day < range.to) return "middle"
    const preview = hoverDay ?? previewDay
    if (preview && day > range.from && day < preview) return "preview"
    return "none"
  }

  const weeks = Array.from({ length: 6 }, (_, w) => days.slice(w * 7, w * 7 + 7))

  const cellSize = size === "md" ? "size-10" : "size-8"
  const weekdayHeight = "h-6"

  const handlePeriodSelect = (date: Date) => {
    if (view === "month") {
      changeMonth(new Date(date.getFullYear(), date.getMonth(), 1))
    } else {
      changeMonth(new Date(date.getFullYear(), visibleMonth.getMonth(), 1))
    }
    setView("days")
    setFocusDay(null)
    focusPending.current = true
  }

  const range = selected as DateRange | undefined
  const rangeActive = mode === "range" && !!range?.from && !range?.to

  if (view !== "days") {
    return (
      <div
        data-slot="calendar"
        className={cn("w-fit", className)}
        onKeyDown={(e) => {
          if (e.key === "Escape") {
            setView("days")
            setFocusDay(null)
            focusPending.current = true
          }
        }}
      >
        <CalendarPeriodPicker
          type={view}
          month={periodPickerMonth}
          selected={mode === "range" ? (range?.from ?? range?.to) : (selected as Date | undefined)}
          today={today}
          min={min}
          max={max}
          onSelect={handlePeriodSelect}
        />
      </div>
    )
  }

  return (
    <div data-slot="calendar" className={cn("flex w-fit flex-col gap-2", className)}>
      <CalendarHeader
        month={visibleMonth}
        type={header}
        navigation={navigation}
        size={size}
        previousDisabled={prevBlocked}
        nextDisabled={nextBlocked}
        onPrevious={() => stepMonth(-1)}
        onNext={() => stepMonth(1)}
        onMonthClick={() => {
          setPeriodPickerMonth(visibleMonth)
          setView("month")
        }}
        onYearClick={() => {
          setPeriodPickerMonth(visibleMonth)
          setView("year")
        }}
        headingId={headingId}
      />
      <div
        ref={gridRef}
        role="grid"
        aria-labelledby={headingId}
        aria-busy={status === "loading" || undefined}
        className="flex flex-col gap-y-0.5"
        onMouseLeave={() => setPreviewDay(null)}
      >
        <div role="row" className="grid grid-cols-7">
          {WEEKDAY_LABELS.map((label, i) => (
            <div
              key={i}
              role="columnheader"
              aria-label={WEEKDAY_NAMES[i]}
              className={cn("flex items-center justify-center text-[11px] font-medium text-text-secondary", weekdayHeight)}
            >
              {label}
            </div>
          ))}
        </div>
        {weeks.map((week, w) => (
          <div key={w} role="row" className="grid grid-cols-7">
            {week.map((day, weekday) => {
              const outside = day.getMonth() !== visibleMonth.getMonth()
              const { selected: isSelected } = dayState(day)
              const isToday = isSameDay(day, today)
              const isBlocked = isDisabled(day)
              const isTabStop = isSameDay(day, activeDay)
              const marked = isMarked(day)
              const selection = daySelection(day)
              const unavailable = status !== "ready" || isBlocked
              const showTooltip = !!disabledReason && isBlocked
              const isHoverDay = isSameDay(day, hoverDay)

              const dayContent = (
                <CalendarDay
                  type="button"
                  size={size}
                  selection={selection}
                  today={isToday}
                  outside={outside}
                  unavailable={unavailable}
                  marked={marked}
                  interaction={isHoverDay ? "hover" : "rest"}
                  tabIndex={isTabStop ? 0 : -1}
                  data-tab-stop={isTabStop ? "" : undefined}
                  onClick={() => handleDayClick(day)}
                  onKeyDown={(e) => handleKeyDown(e, day)}
                  onMouseEnter={() => {
                    if (rangeActive && !outside && day > range.from!) setPreviewDay(day)
                  }}
                  onFocus={() => {
                    if (rangeActive && !outside && day > range.from!) setPreviewDay(day)
                  }}
                  aria-label={`${day.toLocaleDateString("en-US", { weekday: "long", month: "long", day: "numeric", year: "numeric" })}${marked ? `, ${markedLabel}` : ""}${disabledReason && isBlocked ? `, ${disabledReason}` : ""}`}
                  aria-current={isToday ? "date" : undefined}
                  aria-disabled={unavailable || undefined}
                >
                  {day.getDate()}
                </CalendarDay>
              )

              return (
                <div
                  key={weekday}
                  role="gridcell"
                  aria-selected={isSelected}
                  className={cn("relative flex items-center justify-center", cellSize)}
                >
                  {showTooltip ? (
                    <Tooltip defaultOpen={isSameDay(day, reasonDefaultOpenDay)}>
                      <TooltipTrigger render={<div className="flex items-center justify-center" />}>{dayContent}</TooltipTrigger>
                      <TooltipContent side="top">{disabledReason}</TooltipContent>
                    </Tooltip>
                  ) : (
                    dayContent
                  )}
                </div>
              )
            })}
          </div>
        ))}
      </div>
    </div>
  )
}

export { Calendar, CalendarDay, CalendarPeriodPicker, CalendarPeriodCell, CalendarHeader }
export type { CalendarProps, CalendarDayProps, CalendarPeriodPickerProps, CalendarPeriodCellProps, CalendarHeaderProps, DateRange }

import * as React from "react"

const isText = (node: React.ReactNode): node is string | number => typeof node === "string" || typeof node === "number"

/**
 * Puts the text of a circle, pill or badge on the cap-height centre (owner rule, 10 Nov 2026).
 *
 * A flex container centres the line box, and a line box is taller below the baseline than the cap height is
 * above it, so digits and capitals sit a little low. `optical-center` (line-height 1 and `text-box: trim-both
 * cap alphabetic`) shrinks the text to the cap height; it only works on a block of its own, so every run of
 * plain text inside the container is wrapped in a `<span className="optical-center">`. Elements (icons,
 * nested components) are left alone, and so is `null`, `false` and an empty string.
 *
 * Runs of text are merged into one span, so `+{n}` (two text children) stays one flex item.
 */
function opticalCenter(children: React.ReactNode): React.ReactNode {
  const nodes = React.Children.toArray(children)
  if (nodes.length === 0) return children
  const out: React.ReactNode[] = []
  let run: Array<string | number> = []
  const flush = () => {
    if (run.length === 0) return
    out.push(
      <span key={`optical-${out.length}`} className="optical-center">
        {run}
      </span>
    )
    run = []
  }
  for (const node of nodes) {
    if (isText(node)) run.push(node)
    else {
      flush()
      out.push(node)
    }
  }
  flush()
  return out
}

export { opticalCenter }

"use client"

import * as React from "react"
import { Tooltip as TooltipPrimitive } from "@base-ui/react/tooltip"
import { cn } from "@/lib/utils"

const TooltipContext = React.createContext<{ id: string; open: boolean } | null>(null)

/**
 * Shared delay for a group of tooltips, for example a toolbar: the first tooltip opens after
 * `delay` ms, and moving to the next trigger within `timeout` ms shows its tooltip at once.
 */
function TooltipProvider({ delay = 600, closeDelay = 0, timeout = 300, ...props }: TooltipPrimitive.Provider.Props) {
  return (
    <TooltipPrimitive.Provider delay={delay} closeDelay={closeDelay} timeout={timeout} {...props} />
  )
}

function Tooltip({ defaultOpen, open, onOpenChange, ...props }: TooltipPrimitive.Root.Props) {
  const id = React.useId()
  const [uncontrolledOpen, setUncontrolledOpen] = React.useState(defaultOpen ?? false)
  const isOpen = open ?? uncontrolledOpen
  const contextValue = React.useMemo(() => ({ id, open: isOpen }), [id, isOpen])

  return (
    <TooltipContext.Provider value={contextValue}>
      <TooltipPrimitive.Root
        data-slot="tooltip"
        defaultOpen={defaultOpen}
        open={open}
        {...props}
        onOpenChange={(nextOpen, eventDetails) => {
          setUncontrolledOpen(nextOpen)
          onOpenChange?.(nextOpen, eventDetails)
        }}
      />
    </TooltipContext.Provider>
  )
}

function TooltipTrigger({ describe = true, "aria-describedby": ariaDescribedBy, ...props }: TooltipPrimitive.Trigger.Props & { describe?: boolean }) {
  const context = React.useContext(TooltipContext)
  const describedBy = context && describe !== false && context.open
    ? [ariaDescribedBy, context.id].filter(Boolean).join(" ")
    : ariaDescribedBy

  return (
    <TooltipPrimitive.Trigger
      data-slot="tooltip-trigger"
      {...props}
      aria-describedby={describedBy}
    />
  )
}

function TooltipContent({
  className,
  sideOffset = 8,
  children,
  side = "top",
  align,
  anchor,
  shortcut,
  linger = false,
  arrow = true,
  maxWidth = 240,
  ...props
}: TooltipPrimitive.Popup.Props &
  Pick<TooltipPrimitive.Positioner.Props, "sideOffset" | "side" | "align" | "anchor"> & {
    /** Keyboard hint rendered after the label, e.g. "⌘K" (Figma Type=shortcut). */
    shortcut?: string
    /**
     * For confirmations such as "Copied to clipboard": appears at once and,
     * when closed, drifts up slightly while it fades out slowly instead of
     * snapping away.
     */
    linger?: boolean
    /** Show the small point towards the trigger (Figma Show arrow). */
    arrow?: boolean
    /** Widest the label grows before the text wraps onto the next line: 240 px, or 320 px for long translations. */
    maxWidth?: 240 | 320
  }) {
  const context = React.useContext(TooltipContext)
  const maxWidthClass = {
    240: "max-w-60",
    320: "max-w-80",
  } as const

  return (
    <TooltipPrimitive.Portal>
      <TooltipPrimitive.Positioner className="isolate z-50 outline-none" sideOffset={sideOffset} side={side} align={align} anchor={anchor}>
        <TooltipPrimitive.Popup
          data-slot="tooltip-content"
          id={context?.id}
          role="tooltip"
          className={cn(
            // fill-mode-both: the popup is invisible during the enter delay and stays
            // invisible after the exit — without it, it flashes at full opacity at both ends.
            "z-50 inline-flex items-center rounded-md bg-neutral-dark-content px-4 py-2 has-[kbd]:py-[7px] text-xs font-medium text-neutral-white shadow-md fill-mode-both data-open:animate-in data-open:data-instant:animate-none data-closed:data-instant:animate-none data-open:fade-in-0 origin-(--transform-origin) data-open:zoom-in-98 data-open:duration-fast data-open:delay-instant data-open:ease-entrance data-closed:animate-out data-closed:fade-out-0 data-closed:zoom-out-98 data-closed:duration-instant data-closed:ease-exit",
            maxWidthClass[maxWidth],
            linger &&
              "data-open:delay-0 data-open:slide-in-from-bottom-1 data-closed:zoom-out-100 data-closed:slide-out-to-top-1 data-closed:duration-ambient data-closed:ease-move",
            className
          )}
          {...props}
        >
          {children}
          {shortcut && (
            <kbd className="ms-2 inline-flex h-[18px] items-center rounded-sm bg-bg-tooltip-key px-[5px] font-sans text-xs leading-4 font-semibold text-neutral-white shrink-0 whitespace-nowrap">
              {shortcut}
            </kbd>
          )}
          {/* The arrow points down by default (tooltip above the trigger); when the
              tooltip flips or sits beside the trigger it turns to keep pointing at it. */}
          {arrow && (
            <TooltipPrimitive.Arrow className="data-[side=bottom]:top-[-4px] data-[side=bottom]:rotate-180 data-[side=left]:right-[-6px] data-[side=left]:-rotate-90 data-[side=right]:left-[-6px] data-[side=right]:rotate-90 data-[side=top]:bottom-[-4px]">
              <svg width="10" height="5" viewBox="0 0 10 5" fill="none">
                <path d="M0 0L5 5L10 0Z" className="fill-neutral-dark-content" />
              </svg>
            </TooltipPrimitive.Arrow>
          )}
        </TooltipPrimitive.Popup>
      </TooltipPrimitive.Positioner>
    </TooltipPrimitive.Portal>
  )
}

export { Tooltip, TooltipTrigger, TooltipContent, TooltipProvider }

import * as React from "react"
import { Button as ButtonPrimitive } from "@base-ui/react/button"
import { cva, type VariantProps } from "class-variance-authority"
import { Icon } from "@/components/ui/icon-provider"
import { cn } from "@/lib/utils"

// Same states as Button (see button.tsx and the Figma Button / Icon set): the filled variants use fixed
// hover and pressed fills (brand-700/800, red-800/900, dark-400/500, bg-page/bg-subtle on neutral surfaces)
// instead of brightness-95, and focus is the shared 2 px focus-ring (owner rule 31 Oct 2026). The gradient top
// stop is 85 % primary + 15 % brand-500 (4.73:1 with a white icon); hover and pressed step the gradient to
